'use client';

import { forwardRef, type ButtonHTMLAttributes, type ReactNode } from 'react';
import './arrow-capsule-button.css';

export interface ArrowCapsuleButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** A decorative icon. Defaults to a diagonal arrow. */
  icon?: ReactNode;
}

function DiagonalArrow() {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" focusable="false">
      <path
        d="M6 18 18 6M6 6h12v12"
        stroke="currentColor"
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function makeDecorative(node: HTMLSpanElement | null) {
  node?.setAttribute('inert', '');
}

/** A capsule action with a clipped, repeating arrow inside its circular end cap. */
export const ArrowCapsuleButton = forwardRef<HTMLButtonElement, ArrowCapsuleButtonProps>(
  function ArrowCapsuleButton(
    { children, icon, className = '', type = 'button', disabled = false, ...props },
    ref,
  ) {
    const arrow = icon ?? <DiagonalArrow />;

    return (
      <button
        {...props}
        ref={ref}
        type={type}
        disabled={disabled}
        className={`ac-arrow-capsule ${className}`.trim()}
      >
        <span className="ac-arrow-capsule__label">{children}</span>
        <span
          ref={makeDecorative}
          className="ac-arrow-capsule__circle"
          aria-hidden="true"
        >
          <span className="ac-arrow-capsule__icon ac-arrow-capsule__icon--first">
            {arrow}
          </span>
          <span className="ac-arrow-capsule__icon ac-arrow-capsule__icon--next">
            {arrow}
          </span>
        </span>
      </button>
    );
  },
);

export default ArrowCapsuleButton;

.ac-arrow-capsule {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.4em;
  min-width: 44px;
  min-height: 52px;
  max-width: 100%;
  box-sizing: border-box;
  padding: 6px 6px 6px 1.35em;
  border: 1px solid transparent;
  border-radius: 999px;
  background: var(--ac-arrow-bg, #dfe8d4);
  color: var(--ac-arrow-color, #243026);
  font: inherit;
  font-size: 0.95rem;
  font-weight: 550;
  line-height: 1.2;
  text-align: start;
  text-decoration: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
  transition: background-color 180ms ease, box-shadow 180ms ease;
}

.ac-arrow-capsule__label {
  min-width: 0;
  padding-block: 0.2em;
  overflow-wrap: anywhere;
}

.ac-arrow-capsule__circle {
  position: relative;
  display: grid;
  flex: 0 0 38px;
  width: 38px;
  height: 38px;
  overflow: hidden;
  border-radius: 50%;
  background: var(--ac-arrow-circle-bg, #243026);
  color: var(--ac-arrow-circle-color, #f3f6ee);
  pointer-events: none;
}

.ac-arrow-capsule__icon {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  transition: transform 420ms cubic-bezier(0.22, 0.75, 0.15, 1);
}

.ac-arrow-capsule__icon > svg {
  width: 20px;
  height: 20px;
}

.ac-arrow-capsule__icon--next {
  transform: translate(-140%, 140%);
}

.ac-arrow-capsule:not(:disabled):focus-visible {
  outline: 2px solid var(--ac-arrow-focus, #486943);
  outline-offset: 4px;
}

.ac-arrow-capsule:not(:disabled):focus-visible .ac-arrow-capsule__icon--first {
  transform: translate(140%, -140%);
}

.ac-arrow-capsule:not(:disabled):focus-visible .ac-arrow-capsule__icon--next {
  transform: translate(0, 0);
}

@media (hover: hover) and (pointer: fine) {
  .ac-arrow-capsule:not(:disabled):hover {
    background: var(--ac-arrow-hover-bg, #d2dfc4);
  }

  .ac-arrow-capsule:not(:disabled):hover .ac-arrow-capsule__icon--first {
    transform: translate(140%, -140%);
  }

  .ac-arrow-capsule:not(:disabled):hover .ac-arrow-capsule__icon--next {
    transform: translate(0, 0);
  }
}

.ac-arrow-capsule:not(:disabled):active {
  background: var(--ac-arrow-active-bg, #c6d6b7);
  box-shadow: inset 0 0 0 2px var(--ac-arrow-press-ring, #2430261f);
}

.ac-arrow-capsule:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.ac-arrow-capsule:disabled,
.ac-arrow-capsule:disabled .ac-arrow-capsule__icon {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .ac-arrow-capsule,
  .ac-arrow-capsule__icon {
    transition: none;
  }

  .ac-arrow-capsule .ac-arrow-capsule__icon--first {
    transform: none !important;
  }

  .ac-arrow-capsule__icon--next {
    display: none;
  }
}
